#include "Story/ThaddeusPoses.h"

namespace
{
	// The table itself, generated by Tools/dead_friend_poses.py (don't edit it by hand).
#include "Story/ThaddeusPoseData.inl"
}

namespace ThaddeusPoses
{
	const FDeadFriendPoseTable& Table()
	{
		static const FDeadFriendPoseTable Made{ GeneratedBones, GeneratedBoneCount, &GeneratedPoses[0][0], static_cast<int32>(EThaddeusPose::Count) };
		return Made;
	}

	FDeadFriendPose Make(EThaddeusPose Pose)
	{
		return DeadFriendPoses::FromTable(Table(), static_cast<int32>(Pose));
	}

	FDeadFriendPose Measure(float Stretch)
	{
		return FDeadFriendPose::Blend(Make(EThaddeusPose::Together), Make(EThaddeusPose::Idle), Stretch);
	}

	FDeadFriendPose Knock(float Rap)
	{
		return FDeadFriendPose::Blend(Make(EThaddeusPose::KnockUp), Make(EThaddeusPose::KnockDown), Rap);
	}

	const TCHAR* Name(EThaddeusPose Pose)
	{
		static const TCHAR* const Names[] = { TEXT("idle"), TEXT("together"), TEXT("mark"), TEXT("knock_up"), TEXT("knock_down"), TEXT("look"),
			TEXT("talk") };
		static_assert(UE_ARRAY_COUNT(Names) == static_cast<int32>(EThaddeusPose::Count), "A name per pose");
		const int32 Index = static_cast<int32>(Pose);
		return Index >= 0 && Index < static_cast<int32>(EThaddeusPose::Count) ? Names[Index] : TEXT("?");
	}
}
